package io.github.yuroyami.kitearchive.archive

import io.github.yuroyami.kitearchive.archive.ar.ArReader
import io.github.yuroyami.kitearchive.archive.cpio.CpioReader
import kotlin.test.Test
import kotlin.test.assertEquals

class ArCpioTest {

    private val alpha = "hello from alpha\n"
    private val beta = "beta beta beta beta\n"

    private val arVector = hex("")
    private val cpioNewc = hex("")
    private val cpioOdc = hex("")

    @Test
    fun readsArArchive() {
        val r = ArReader(ByteArrayRandomAccessSource(arVector))
        val byName = r.entries().associateBy { it.name }
        assertEquals(alpha, r.read(byName.getValue("alpha.txt")).decodeToString())
        assertEquals(beta, r.read(byName.getValue("beta.txt")).decodeToString())
    }

    @Test
    fun readsCpioNewc() {
        val r = CpioReader(ByteArrayRandomAccessSource(cpioNewc))
        val byName = r.entries().filterNot { it.isDirectory }.associateBy { it.name }
        assertEquals(alpha, r.read(byName.getValue("alpha.txt")).decodeToString())
        assertEquals(beta, r.read(byName.getValue("beta.txt")).decodeToString())
    }

    @Test
    fun readsCpioOdc() {
        val r = CpioReader(ByteArrayRandomAccessSource(cpioOdc))
        val byName = r.entries().filterNot { it.isDirectory }.associateBy { it.name }
        assertEquals(alpha, r.read(byName.getValue("alpha.txt")).decodeToString())
        assertEquals(beta, r.read(byName.getValue("beta.txt")).decodeToString())
    }

    private fun hex(s: String): ByteArray =
        ByteArray(s.length / 2) {
            ((s[it * 2].digitToInt(16) shl 4) or s[it * 2 + 1].digitToInt(16)).toByte()
        }
}
